jQuery(document).ready(function($){'use strict';var $propertyForm=$('#post');if($propertyForm.length){restoreFormData();$propertyForm.on('submit',function(){saveFormData();});setInterval(saveFormData,30000);if(window.location.search.indexOf('message=')>-1){clearSavedData();}}function saveFormData(){var formData={};$propertyForm.find('input[type="text"],input[type="number"],input[type="email"],input[type="tel"],input[type="url"],textarea,select').each(function(){var $field=$(this);var name=$field.attr('name');if(name&&!name.match(/^(post_ID|_wpnonce|_wp_http_referer|action)/)){formData[name]=$field.val();}});$propertyForm.find('input[type="checkbox"]').each(function(){var $field=$(this);var name=$field.attr('name');if(name&&!name.match(/^(post_ID|_wpnonce|_wp_http_referer|action)/)){formData[name]=$field.is(':checked');}});$propertyForm.find('input[type="radio"]:checked').each(function(){var $field=$(this);var name=$field.attr('name');if(name){formData[name]=$field.val();}});var galleryIds=[];$('input[name="malisafi_gallery_ids[]"]').each(function(){galleryIds.push($(this).val());});if(galleryIds.length>0){formData['malisafi_gallery_ids']=galleryIds;}try{sessionStorage.setItem('malisafi_property_form_data',JSON.stringify(formData));sessionStorage.setItem('malisafi_property_form_timestamp',Date.now());}catch(e){}}function restoreFormData(){try{var savedData=sessionStorage.getItem('malisafi_property_form_data');var timestamp=sessionStorage.getItem('malisafi_property_form_timestamp');if(!savedData||!timestamp){return;}var age=Date.now()-parseInt(timestamp);if(age>3600000){clearSavedData();return;}var formData=JSON.parse(savedData);var hasErrors=$('.error,.notice-error').length>0;if(!hasErrors&&$('#title').val().trim()!==''){return;}$.each(formData,function(name,value){if(name==='malisafi_gallery_ids'){return;}var $field=$('[name="'+name+'"]');if($field.length){if($field.is(':checkbox')){$field.prop('checked',value===true);}else if($field.is(':radio')){$field.filter('[value="'+value+'"]').prop('checked',true);}else{$field.val(value);}}});if(hasErrors){var $notice=$('<div class="notice notice-success is-dismissible" style="margin:10px 0;"><p><strong>Form data restored.</strong>Your previous entries have been recovered.</p></div>');$('.wrap h1').after($notice);$notice.on('click','.notice-dismiss',function(){$notice.fadeOut();});}}catch(e){}}function clearSavedData(){try{sessionStorage.removeItem('malisafi_property_form_data');sessionStorage.removeItem('malisafi_property_form_timestamp');}catch(e){}}$('#clear-saved-data').on('click',function(e){e.preventDefault();clearSavedData();alert('Saved form data cleared.');});});